describe('Request Timeout Error Handling', () => {
  beforeEach(() => {
    cy.visit('http://localhost:3000');
  });

  it('should display timeout error when request exceeds 10 seconds', () => {
    cy.intercept('GET', '/api/slow-endpoint', (req) => {
      req.reply((res) => {
        res.delay(11000);
        res.send({
          statusCode: 200,
          body: { data: 'test' }
        });
      });
    }).as('slowRequest');

    cy.get('[data-testid="fetch-button"]').click();
    cy.wait('@slowRequest', { timeout: 12000 });

    cy.get('[data-testid="error-message"]')
      .should('be.visible')
      .and('contain', 'Request timeout');

    cy.get('[data-testid="error-icon"]')
      .should('have.class', 'error-state');
  });

  it('should successfully complete request within 10 seconds', () => {
    cy.intercept('GET', '/api/fast-endpoint', (req) => {
      req.reply((res) => {
        res.delay(5000);
        res.send({
          statusCode: 200,
          body: { data: 'success' }
        });
      });
    }).as('fastRequest');

    cy.get('[data-testid="fetch-button"]').click();
    cy.wait('@fastRequest', { timeout: 10000 });

    cy.get('[data-testid="success-message"]')
      .should('be.visible')
      .and('contain', 'Request completed successfully');

    cy.get('[data-testid="error-message"]')
      .should('not.exist');
  });

  it('should handle timeout error retry mechanism', () => {
    let requestCount = 0;

    cy.intercept('GET', '/api/retry-endpoint', (req) => {
      requestCount++;
      req.reply((res) => {
        if (requestCount === 1) {
          res.delay(11000);
        } else {
          res.delay(3000);
        }
        res.send({
          statusCode: 200,
          body: { data: 'retried' }
        });
      });
    }).as('retryRequest');

    cy.get('[data-testid="fetch-button"]').click();
    cy.wait('@retryRequest', { timeout: 12000 });

    cy.get('[data-testid="error-message"]')
      .should('be.visible');

    cy.get('[data-testid="retry-button"]')
      .should('be.visible')
      .click();

    cy.wait('@retryRequest', { timeout: 10000 });

    cy.get('[data-testid="success-message"]')
      .should('be.visible')
      .and('contain', 'Request completed successfully');

    cy.get('[data-testid="error-message"]')
      .should('not.exist');
  });

  it('should display appropriate error message for network timeout vs server timeout', () => {
    cy.intercept('GET', '/api/network-timeout', (req) => {
      req.destroy();
    }).as('networkTimeout');

    cy.get('[data-testid="fetch-button"]').click();

    cy.get('[data-testid="error-message"]')
      .should('be.visible')
      .and('contain', 'Network error or request timeout');

    cy.get('[data-testid="error-details"]')
      .should('contain', 'Please check your connection');
  });
});
